import React from 'react';
import Card from './Card';

const Hand = ({ cards, isPlayer = true, onCardClick, disabled = false, selectedRank = null }) => {
  // Group cards by rank for player display
  const groupedCards = cards.reduce((acc, card) => {
    if (!acc[card.rank]) {
      acc[card.rank] = [];
    }
    acc[card.rank].push(card);
    return acc;
  }, {});

  const handleCardClick = (card) => {
    if (isPlayer && onCardClick) {
      onCardClick(card.rank);
    }
  };

  return (
    <div className="p-4">
      <h3 className="text-white text-lg font-semibold mb-3 flex items-center gap-2">
        {isPlayer ? '🎴 Your Hand' : '🤖 AI Hand'}
        <span className="text-sm font-normal text-gray-300">
          ({cards.length} cards)
        </span>
      </h3>
      
      <div className="flex flex-wrap gap-2 justify-center">
        {isPlayer ? (
          // Show grouped cards for player (easier to select ranks)
          Object.entries(groupedCards).map(([rank, rankCards]) => (
            <div key={rank} className="flex -space-x-8 md:-space-x-10 hover:space-x-1 transition-all duration-300">
              {rankCards.map((card, index) => (
                <div key={card.id} style={{ zIndex: index }}>
                  <Card
                    card={card}
                    onClick={() => handleCardClick(card)}
                    disabled={disabled}
                    selected={selectedRank === card.rank}
                  />
                </div>
              ))}
            </div>
          ))
        ) : (
          // Show face-down cards for AI
          cards.map((card, index) => (
            <div 
              key={card.id} 
              className="-ml-8 md:-ml-10 first:ml-0"
              style={{ zIndex: index }}
            >
              <Card card={card} faceDown />
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Hand;
